    TwistSquash::SquashKeyA(BELLATRIX_KEY_B_D_IceLaneA, BELLATRIX_KEY_B_D_IceLaneB, BELLATRIX_KEY_B_D_IceLaneC, BELLATRIX_KEY_B_D_IceLaneD, &(pWorkSpace->mKeyBoxB[3U][0]));

    // Key flow — B / E

