    TwistSquash::SquashKeyA(BELLATRIX_KEY_B_E_IceLaneA, BELLATRIX_KEY_B_E_IceLaneB, BELLATRIX_KEY_B_E_IceLaneC, BELLATRIX_KEY_B_E_IceLaneD, &(pWorkSpace->mKeyBoxB[4U][0]));

